#!/usr/bin/env bash
# Writes the 3 marketplace backend files: crop model, controller, route.
set -euo pipefail
if [ ! -d src/routes ]; then echo "ERROR: run from ~/Documents/AgroMart/backend"; exit 1; fi
mkdir -p src/models src/controllers src/routes
echo '' | base64 -d > 'src/models/crop.model.js' && echo '  wrote src/models/crop.model.js'
echo '' | base64 -d > 'src/controllers/crops.controller.js' && echo '  wrote src/controllers/crops.controller.js'
echo '' | base64 -d > 'src/routes/crops.routes.js' && echo '  wrote src/routes/crops.routes.js'
echo ""; echo "Done. nodemon will auto-restart. Then: curl -s http://localhost:4000/api/crops | head -c 200"
